<?php
namespace CloudHost247\Ovh\Catalog;use CloudHost247\Ovh\Services\ConnectionResolver;use WHMCS\Database\Capsule;use RuntimeException;
final class CatalogService
{private $resolver;function __construct(ConnectionResolver$r){$this->resolver=$r;}function sync($endpointId,$subsidiary='US',$family='eco'){$family=in_array($family,array('eco','vps'),true)?$family:null;if(!$family)throw new RuntimeException('Unsupported catalog family.');$client=$this->resolver->endpoint($endpointId);$data=$client->get('/order/catalog/public/'.rawurlencode($family).'?ovhSubsidiary='.rawurlencode(strtoupper($subsidiary)));if(!isset($data['plans'])||!is_array($data['plans']))throw new RuntimeException('Catalog response contains no plans.');$seen=array();foreach($data['plans'] as $plan){if(empty($plan['planCode']))continue;$code=(string)$plan['planCode'];$seen[]=$code;Capsule::table('mod_cloudhost247_ovh_catalog')->updateOrInsert(array('endpoint_id'=>$endpointId,'family'=>$family,'plan_code'=>$code),array('invoice_name'=>isset($plan['invoiceName'])?substr($plan['invoiceName'],0,255):null,'currency'=>$data['locale']['currencyCode']??null,'catalog_json'=>json_encode($plan),'available'=>1,'last_seen_at'=>date('Y-m-d H:i:s')));}Capsule::table('mod_cloudhost247_ovh_catalog')->where('endpoint_id',$endpointId)->where('family',$family)->whereNotIn('plan_code',$seen?:array(''))->update(array('available'=>0));return count($seen);}}
